parameters.jsCode:
/* === Decide whether this agent reply must be delivered to the customer over WhatsApp === */
const FALLBACK_ID = 'a0000000-0000-0000-0000-000000000001';
const ticket = $('Lookup Ticket & Customer').first()?.json || {};
const recorded = $('Record Agent Message').first()?.json || {};
const hook = $('Agent Response Webhook').first()?.json || {};
const body = hook.body || hook;
const message = String(body.agent_message || body.agent_response || '').trim();

// Only real tickets on WhatsApp conversations with a known address are sent; the lookup's
// placeholder row (unknown ticket number) must never produce a message to anyone.
const recipient = String(ticket.whatsapp_id || ticket.phone_number || '');
const deliver = ticket.ticket_id && ticket.ticket_id !== FALLBACK_ID
  && ticket.channel === 'whatsapp' && recipient !== '' && message !== '';

return [{
  json: {
    channel: 'whatsapp',
    explicit_dispatch: Boolean(deliver),
    whatsapp_id: ticket.whatsapp_id || '',
    phone_number: ticket.phone_number || '',
    reply: message,
    lifecycle_message_id: recorded.id || null,
    ticket_number: ticket.ticket_number || null,
    skip_reason: deliver ? null : 'not_a_whatsapp_ticket_or_missing_recipient'
  }
}];
